1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create-owner request whose telephone is already used by another owner,
10	 * responding 409. Runs after {@link NormalizeOwnerTelephone} so the comparison is
11	 * between normalized values, and before {@link BuildOwner} persists a duplicate.
12	 */
13	public class EnsureUniqueTelephone {
14	
15	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
16	            throws DuplicateTelephoneException {
17	        if (!ownerRepository.findByTelephone(request.getTelephone()).isEmpty()) {
18	            throw new DuplicateTelephoneException(request.getTelephone());
19	        }
20	    }
21	}
